def transform(g):
    H,W=len(g),len(g[0])
    r0=[r for r in range(H) if all(v==3 for v in g[r])]
    c0=[c for c in range(W) if all(g[r][c]==3 for r in range(H))]
    ry,rx=r0[0],c0[0]
    out=[row[:] for row in g]
    k=1
    while True:
        t,b,l,r=ry-2*k,ry+2*k,rx-2*k,rx+2*k
        if t>H-1 and b<0 and l>W-1 and r<0: break
        if t>=0:
            for c in range(max(0,l),min(W-1,r)+1):
                if out[t][c]!=3: out[t][c]=4
        if b<=H-1:
            for c in range(max(0,l),min(W-1,r)+1):
                if out[b][c]!=3: out[b][c]=4
        if l>=0:
            for rr in range(max(0,t),min(H-1,b)+1):
                if out[rr][l]!=3: out[rr][l]=4
        if r<=W-1:
            for rr in range(max(0,t),min(H-1,b)+1):
                if out[rr][r]!=3: out[rr][r]=4
        k+=1
    return out
